; Title logo letters
; $8492-$84c8

; Draws the logo letter of the column $02 - 4 at row 3 in yellow, when title_logo_letters has one there. Then sets $02 back, $03 to row 6, $04 to the mown grass $59 and $05 to green.
title_draw_logo_letter
        lda cursor_col
        sta work_temp
        sec
        sbc #$04
        sta cursor_col
        and #$80
        beq title_logo_draw
        lda work_temp
        sta cursor_col
        rts
title_logo_draw
        lda #$03
        sta cursor_row
        lda #$07
        sta cursor_colour
        ldx cursor_col
        lda title_logo_letters,x
        sta cursor_char
        beq title_logo_restore
        jsr draw_block_2x2
title_logo_restore
        lda #$59
        sta cursor_char
        lda #$05
        sta cursor_colour
        lda work_temp
        sta cursor_col
        lda #$06
        sta cursor_row
        rts
